customCss:
/* ── MUNDO AFORA — Viagens & Aventura ── */
@import url('https://fonts.googleapis.com/css2?family=PT+Sans:wght@400;700&family=Allerta+Stencil&display=swap');

:root {
  --nat-primary: #0ea5e9;
  --nat-accent:  #0d9488;
  --nat-bg:      #f0f9ff;
  --nat-footer:  #0c1a2e;
  --nat-text:    #1e293b;
  --nat-card:    #ffffff;
  --nat-border:  #e0f2fe;
  --nat-muted:   #64748b;
}

body {
  background-color: var(--nat-bg);
  color: var(--nat-text);
  font-family: 'PT Sans', sans-serif;
}

/* Card — Organic Rounded (padrão natureza RAG) */
.sl-card {
  background-color: var(--nat-card);
  border: none;
  border-radius: 1.25rem;
  box-shadow: 0 0.4rem 1rem rgba(0,0,0,0.08);
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  overflow: hidden;
}
.sl-card:hover {
  box-shadow: 0 0.8rem 1.8rem rgba(0,0,0,0.15), 0 0 0 3px var(--nat-primary);
  transform: translateY(-6px) scale(1.01);
}
.sl-card .card-img-top {
  object-fit: cover;
  height: 200px;
  width: 100%;
}

/* Navbar */
.navbar {
  background-color: #ffffff !important;
  border-bottom: 2px solid var(--nat-primary);
  font-family: 'Allerta Stencil', sans-serif;
  letter-spacing: 0.04em;
}
.navbar-brand {
  color: var(--nat-primary) !important;
  font-size: 1.4rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.nav-link {
  color: var(--nat-text) !important;
  font-size: 0.85rem;
  text-transform: uppercase;
}
.nav-link:hover { color: var(--nat-primary) !important; }

/* Badges de categoria */
.badge-category {
  background-color: var(--nat-primary);
  color: #fff;
  border-radius: 50rem;
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 0.2em 0.7em;
}

/* Sidebar */
.sidebar-widget {
  background: #ffffff;
  border-radius: 1rem;
  padding: 1.25rem;
  margin-bottom: 1.5rem;
  border: 1px solid var(--nat-border);
}
.sidebar-widget h3 {
  font-family: 'Allerta Stencil', sans-serif;
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--nat-primary);
  border-bottom: 2px solid var(--nat-border);
  padding-bottom: 0.5rem;
  margin-bottom: 1rem;
}

/* Footer */
footer {
  background-color: var(--nat-footer);
  color: #94a3b8;
}
footer a { color: #7dd3fc; }
footer a:hover { color: #0ea5e9; }
footer h5 {
  font-family: 'Allerta Stencil', sans-serif;
  color: #f1f5f9;
  letter-spacing: 0.06em;
}

/* Botões */
.btn-primary {
  background: linear-gradient(135deg, var(--nat-primary), var(--nat-accent));
  border: none;
  border-radius: 50rem;
  font-weight: 600;
  letter-spacing: 0.04em;
}
.btn-primary:hover {
  background: linear-gradient(135deg, #0284c7, #0f766e);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(14,165,233,0.35);
}
.btn-outline-primary {
  border-color: var(--nat-primary);
  color: var(--nat-primary);
  border-radius: 50rem;
}
.btn-outline-primary:hover {
  background-color: var(--nat-primary);
  color: #fff;
}
